mapper.select:
select t.come_id,t.come_id comeId,t.come_type,t.come_type comeType,t.mf_id,t.mf_id mfId,t.status_cd,t.status_cd
statusCd,t.id_number,t.id_number idNumber,t.message,t.machine_id,t.machine_id
machineId,t.name,t.person_id,t.person_id personId,t.start_time,t.start_time startTime,t.end_time,t.end_time
endTime,t.face_path,t.face_path facePath,t.state,t.person_type,t.person_type
personType,t.community_id,t.community_id communityId,t.card_number,t.card_number cardNumber,t.room_name roomName,
ac.machine_code machineCode,ac.machine_name machineName,td.`name` comeTypeName,td1.name stateName,t.create_time createTime
from access_control_face t
left join access_control ac on ac.machine_id = t.machine_id and ac.status_cd = '0'
left join t_dict td on t.come_type = td.status_cd and td.table_name = 'access_control_face' and td.table_columns = 'come_type'
left join t_dict td1 on t.state = td1.status_cd and td1.table_name = 'access_control_face' and td1.table_columns = 'state'
where 1 =1

    and t.come_id= #{comeId}


    and t.come_type= #{comeType}


    and t.mf_id= #{mfId}


    and t.status_cd= #{statusCd}


    and t.id_number= #{idNumber}


    and t.message= #{message}


    and t.machine_id= #{machineId}


    and t.name= #{name}


    and t.person_id= #{personId}


    and t.start_time= #{startTime}


    and t.end_time= #{endTime}


    and t.face_path= #{facePath}


    and t.state= #{state}


    and t.person_type= #{personType}


    and t.community_id= #{communityId}


    and t.card_number= #{cardNumber}


    and t.create_time >= #{queryStartTime}


    and t.create_time <= #{queryEndTime}

order by t.create_time desc

    limit #{page}, #{row}

